'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),model=require('./reading-pilot.js');const ctx={window:{}};vm.runInNewContext(fs.readFileSync(__dirname+'/white-orchard.js','utf8'),ctx);const task=ctx.window.PHOENIX_ROUTE.tasks['q-lilac'];
test('all seven pilot steps preserve every original instruction and supporting paragraph without changing source',()=>{const original=JSON.stringify(task);assert.equal(task.stages.length,7);for(const s of task.stages){const p=model.plan(s),paras=p.support.flatMap(d=>d.paragraphs);assert.ok(p.brief.do);assert.ok(p.brief.where);assert.equal(paras.filter(t=>t===s.text).length,1);for(const d of s.details||[])for(const text of d.paragraphs)assert.equal(paras.filter(t=>t===text).length,1);}assert.equal(JSON.stringify(task),original);});
test('empty categories and invented preparation are omitted',()=>{assert.equal(model.plan({id:'unrelated'}),null);for(const s of task.stages){const p=model.plan(s);assert.ok(p.support.every(d=>d.paragraphs.length));if(s.id!=='1')assert.equal(p.brief.needed,undefined);}});
test('arrival glow skips returns, repeated renders, other quests and within-quest steps',()=>{assert.equal(model.shouldCue({current:'pilot',previous:'hub',mode:'push',pilot:'pilot'}),true);assert.equal(model.shouldCue({current:'pilot',previous:'hub',mode:'initial',pilot:'pilot'}),true);for(const params of [{current:'pilot',previous:'pilot',mode:'push'},{current:'pilot',previous:'activity',mode:'pop'},{current:'pilot',previous:'hub',mode:'same'},{current:'other',previous:'hub',mode:'push'}])assert.equal(model.shouldCue({...params,pilot:'pilot'}),false);});
test('foldout keys distinguish steps and restore only valid boolean preferences',()=>{const keys=['quest/1/route','quest/2/route'];assert.deepEqual(model.preferences({'quest/1/route':true,'quest/2/route':false,other:true},keys),{'quest/1/route':true,'quest/2/route':false});assert.deepEqual(model.preferences({'quest/1/route':'true'},keys),{});assert.deepEqual(model.preferences(null,keys),{});});
